(() => {
  const form=document.querySelector('#checkout-form');if(!form)return;document.head.insertAdjacentHTML('beforeend','<style>.field-invalid{border-color:#dc2626!important;background:#fff7f7!important}.field-error{display:block;color:#dc2626;font-size:.76rem;font-weight:600;margin-top:-3px}</style>');
  const iso='AF,AL,DZ,AS,AD,AO,AI,AQ,AG,AR,AM,AW,AU,AT,AZ,BS,BH,BD,BB,BY,BE,BZ,BJ,BM,BT,BO,BA,BW,BR,IO,BN,BG,BF,BI,CV,KH,CM,CA,KY,CF,TD,CL,CN,CX,CC,CO,KM,CG,CD,CK,CR,CI,HR,CU,CW,CY,CZ,DK,DJ,DM,DO,EC,EG,SV,GQ,ER,EE,SZ,ET,FK,FO,FJ,FI,FR,GF,PF,TF,GA,GM,GE,DE,GH,GI,GR,GL,GD,GP,GU,GT,GG,GN,GW,GY,HT,HM,VA,HN,HK,HU,IS,IN,ID,IR,IQ,IE,IM,IL,IT,JM,JP,JE,JO,KZ,KE,KI,KP,KR,KW,KG,LA,LV,LB,LS,LR,LY,LI,LT,LU,MO,MG,MW,MY,MV,ML,MT,MH,MQ,MR,MU,YT,MX,FM,MD,MC,MN,ME,MS,MA,MZ,MM,NA,NR,NP,NL,NC,NZ,NI,NE,NG,NU,NF,MK,MP,NO,OM,PK,PW,PS,PA,PG,PY,PE,PH,PN,PL,PT,PR,QA,RE,RO,RU,RW,BL,SH,KN,LC,MF,PM,VC,WS,SM,ST,SA,SN,RS,SC,SL,SG,SX,SK,SI,SB,SO,ZA,GS,SS,ES,LK,SD,SR,SJ,SE,CH,SY,TW,TJ,TZ,TH,TL,TG,TK,TO,TT,TN,TR,TM,TC,TV,UG,UA,AE,GB,US,UM,UY,UZ,VU,VE,VN,VG,VI,WF,EH,YE,ZM,ZW'.split(',');
  const dial={ID:'+62',US:'+1',GB:'+44',CN:'+86',JP:'+81',KR:'+82',SG:'+65',MY:'+60',TH:'+66',VN:'+84',PH:'+63',AU:'+61',AE:'+971',IN:'+91'};
  const names=new Intl.DisplayNames(['id'],{type:'region'});
  const flag=code=>String.fromCodePoint(...[...code].map(c=>127397+c.charCodeAt()));
  document.querySelectorAll('.country-select,.phone-country').forEach(select=>{const phone=select.classList.contains('phone-country'),defaultCountry=select.dataset.default||'ID';select.replaceChildren(...iso.map(country=>new Option(`${flag(country)} ${names.of(country)}${phone?` (${dial[country]||'+'})`:''}`,phone?(dial[country]||'+'):country)));select.value=phone?(dial[defaultCountry]||'+'):defaultCountry});
  let choice;try{choice=JSON.parse(sessionStorage.getItem('jtm-flight-choice')||'')}catch{};if(!choice?.flight){document.querySelector('#checkout-feedback').textContent='Pilih penerbangan terlebih dahulu.';return}const first=choice.flight.flights?.[0]||{},last=choice.flight.flights?.at(-1)||first,money=new Intl.NumberFormat('id-ID',{style:'currency',currency:choice.search.currency,maximumFractionDigits:0});document.querySelector('#checkout-route').textContent=`${choice.labels?.origin||choice.search.origin} → ${choice.labels?.destination||choice.search.destination}`;document.querySelector('#checkout-airline').textContent=`${first.airline||''} ${first.flight_number||''}`;document.querySelector('#checkout-date').textContent=new Intl.DateTimeFormat('id-ID',{dateStyle:'medium'}).format(new Date(`${choice.search.departure}T12:00:00`));document.querySelector('#checkout-passengers').textContent=`${choice.search.adults+choice.search.children+choice.search.infants} penumpang`;document.querySelector('#checkout-total').textContent=money.format(choice.flight.price);document.querySelector('.order-summary small').textContent='Pembayaran akan ditagihkan dalam Rupiah Indonesia (IDR). Harga hasil pencarian bersifat indikatif dan ketersediaan dikonfirmasi sebelum tiket diterbitkan.';
  const travelDate=choice.search.departure;const passengerTypes=[...Array(choice.search.adults).fill('Dewasa'),...Array(choice.search.children).fill('Anak'),...Array(choice.search.infants).fill('Bayi')];const identity=form.querySelector('fieldset');identity.querySelector('legend').textContent=`Penumpang 1 — ${passengerTypes[0]||'Dewasa'}`;passengerTypes.slice(1).forEach((type,index)=>{const clone=identity.cloneNode(true);clone.querySelector('legend').textContent=`Penumpang ${index+2} — ${type}`;clone.querySelectorAll('input,select').forEach(input=>{input.value='';if(input.name)input.name=`passenger${index+2}_${input.name}`;if(input.type==='date')input.max=travelDate});identity.after(clone)});
  const today=new Date().toISOString().slice(0,10),birth=form.querySelector('[name="birthDate"]');birth.max=today;form.noValidate=true;form.querySelector('[name="emailConfirmation"]').addEventListener('paste',event=>event.preventDefault());form.querySelector('[name="phone"]').addEventListener('input',event=>event.target.value=event.target.value.replace(/\D/g,''));
  const dateShift=(years,days=0)=>{const d=new Date(`${travelDate}T12:00:00`);d.setFullYear(d.getFullYear()+years);d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)};form.querySelectorAll('fieldset').forEach((section,index)=>{const type=passengerTypes[index]||'Dewasa',field=section.querySelector('input[type="date"]');if(!field)return;if(type==='Dewasa'){field.max=dateShift(-12)}else if(type==='Anak'){field.min=dateShift(-12,1);field.max=dateShift(-2,-1)}else{field.min=dateShift(-2,1);field.max=travelDate}});
  const clear=input=>{input.classList.remove('field-invalid');input.parentElement.querySelector('.field-error')?.remove()};const invalid=(input,message)=>{clear(input);input.classList.add('field-invalid');input.insertAdjacentHTML('afterend',`<small class="field-error">${message}</small>`)};
  document.addEventListener('submit',event=>{if(event.target!==form)return;let firstInvalid;form.querySelectorAll('[required]').forEach(input=>{if((input.type==='checkbox'&&!input.checked)||input.type!=='checkbox'&&!input.value){invalid(input,'Field ini wajib diisi.');firstInvalid||=input}if(input.type==='date'&&input.value&&(input.min&&input.value<input.min||input.max&&input.value>input.max)){invalid(input,'Tanggal lahir tidak sesuai kategori penumpang.');firstInvalid||=input}});if(firstInvalid){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();firstInvalid.focus()}},true);
  form.querySelectorAll('input,select').forEach(input=>input.addEventListener('input',()=>clear(input)));
  document.addEventListener('submit',event=>{if(event.target!==form)return;let first;const require=['firstName','lastName','gender','birthDate','nationality','email','emailConfirmation','phoneCountry','phone','consent'];require.forEach(name=>{const input=form.querySelector(`[name="${name}"]`);if(!input?.value||input.type==='checkbox'&&!input.checked){invalid(input,'Field ini wajib diisi.');first||=input}});if(birth.value&&birth.value>today){invalid(birth,'Tanggal lahir tidak boleh di masa depan.');first||=birth}const email=form.querySelector('[name="email"]'),confirm=form.querySelector('[name="emailConfirmation"]');if(email.value&&confirm.value&&email.value!==confirm.value){invalid(confirm,'Email verifikasi harus sama dengan email.');first||=confirm}if(first){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();first.focus()}},true);
  form.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();const feedback=document.querySelector('#checkout-feedback'),button=form.querySelector('button[type=submit]'),fields=Object.fromEntries(new FormData(form));button.disabled=true;feedback.textContent='Mengirim permintaan…';try{const response=await fetch('/api/flights/submit.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,route:document.querySelector('#checkout-route').textContent,price:document.querySelector('#checkout-total').textContent,airline:document.querySelector('#checkout-airline').textContent,date:document.querySelector('#checkout-date').textContent,passengers:document.querySelector('#checkout-passengers').textContent})}),data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.message||'Permintaan tidak dapat dikirim.');sessionStorage.setItem('jtm-order',JSON.stringify({number:data.reference,customer:fields}));location.assign(`/order-confirmation/?order=${encodeURIComponent(data.reference)}`)}catch(error){feedback.textContent=error.message}finally{button.disabled=false}},true)
})();
